package com.gomgomapps.math.core;
import java.util.*;import java.io.*;import org.junit.Test;import static org.junit.Assert.*;
public class ContextInverseCheckTest {
 @Test public void ownProposalPublicInverseAndComparisonForAllOperations(){for(int op=0;op<4;op++){Question q=ContextCalculationMethods.make(op,12,3);q.answers=new String[]{"poison"};q.expression="poison";String correct=new String[]{"15","9","36","4"}[op];var plan=ContextInverseCheck.plan(q,correct);assertEquals(Rational.of(12),plan.recovered());assertEquals(ContextInverseCheck.Status.CONSISTENT,ContextInverseCheck.check(q,correct,"12","same"));assertEquals(ContextInverseCheck.Status.WRONG_VALUE,ContextInverseCheck.check(q,correct,"13","same"));assertEquals(ContextInverseCheck.Status.WRONG_COMPARISON,ContextInverseCheck.check(q,correct,"12","different"));String wrong=""+(Integer.parseInt(correct)+1);var bad=ContextInverseCheck.plan(q,wrong);assertEquals(ContextInverseCheck.Status.INCONSISTENT,ContextInverseCheck.check(q,wrong,bad.recovered().toString(),"different"));assertFalse(new Checker().check(q,List.of(),List.of(wrong)).correct());}}
 @Test public void negativeFractionLargeWrongRecoveryAndZeroMultiplicationRemainHonest(){Question add=ContextCalculationMethods.make(0,10,20);assertEquals(Rational.of(-19),ContextInverseCheck.plan(add,"1").recovered());assertEquals(ContextInverseCheck.Status.INCONSISTENT,ContextInverseCheck.check(add,"1","-19","different"));Question mul=ContextCalculationMethods.make(2,10,2);assertEquals(ContextInverseCheck.Status.INCONSISTENT,ContextInverseCheck.check(mul,"3","3/2","different"));Question sub=ContextCalculationMethods.make(1,1000000,1000000);assertEquals(Rational.of(2000000),ContextInverseCheck.plan(sub,"1000000").recovered());assertEquals(ContextInverseCheck.Status.INCONSISTENT,ContextInverseCheck.check(sub,"1000000","2000000","different"));Question zero=ContextCalculationMethods.make(2,1000000,0);assertEquals(ContextInverseCheck.Status.UNAVAILABLE,ContextInverseCheck.check(zero,"0","0","same"));assertTrue(new Checker().check(zero,List.of(),List.of("0")).correct());assertNull(ContextInverseCheck.plan(add,""));assertNull(ContextInverseCheck.plan(add,"1000001"));assertEquals(ContextInverseCheck.Status.INPUT_NEEDED,ContextInverseCheck.check(add,"30","1/0","same"));}
 @Test public void draftIsIndependentOfIdentityAnswerAndOriginalWork()throws Exception {Question q=ContextCalculationMethods.make(1,929349,1769);String id=q.signature();q.inverseProposal="1";q.inverseValue="1771";q.inverseVerdict="different";q.inverseChecked=true;assertEquals(id,q.signature());ByteArrayOutputStream b=new ByteArrayOutputStream();new ObjectOutputStream(b).writeObject(q);Question copy=(Question)new ObjectInputStream(new ByteArrayInputStream(b.toByteArray())).readObject();assertEquals(id,copy.signature());assertEquals("1771",copy.inverseValue);assertEquals(ContextInverseCheck.Status.WRONG_VALUE,ContextInverseCheck.check(copy,copy.inverseProposal,copy.inverseValue,copy.inverseVerdict));assertEquals("927580",copy.answers[0]);assertTrue(new Checker().check(copy,List.of(),List.of("927580")).correct());}
}
